mapper.select:
select wrd.purchase_order_detail_id as podId, sum(wrd.receive_qty) as totalReceiveQty from po_receive_detail wrd inner join po_receive wr on wr.id = wrd.main_id and wr.is_deleted = false where wrd.is_deleted = false and wr.invalid_status = false and wrd.purchase_order_detail_id in
#{item}
group by wrd.purchase_order_detail_id

select wrd.purchase_order_detail_id as podId, wrd.id as detailId, sum(wrd.wait_qc_qty) as totalWaitQcQty from po_receive_detail wrd inner join po_receive wr on wr.id = wrd.main_id and wr.is_deleted = false where wrd.is_deleted = false and wr.invalid_status = false and wrd.purchase_order_detail_id in
#{item}
group by wrd.purchase_order_detail_id,wrd.id

mapper.update:
UPDATE po_receive_detail
SET in_stock_status=#{inStockStatus}
WHERE id = #{id}
  AND is_deleted = false
